  // TODO: return the sum (0 for empty)
  return 0;
}

console.log(sumArray([1, 2, 3, 4]));

solutionCode:
function sumArray(arr: number[]): number {
  return arr.reduce((total, n) => total + n, 0);
}

console.log(sumArray([1, 2, 3, 4]));

